INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Takut Salah Nada Saat Bicara Bahasa Vietnam$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Bahasa Vietnam memakai 6 nada yang mengubah arti kata: kata yang sama dengan nada berbeda bisa berarti ibu, hantu, atau nasi. Banyak pemula takut salah nada sehingga tidak berani bicara sama sekali. Padahal, orang Vietnam sangat menghargai usaha orang asing yang mencoba berbahasa mereka — satu sapaan yang benar sudah membuka pintu percakapan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: 6 Nada Bahasa Vietnam$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Bahasa Vietnam adalah bahasa tonal seperti Mandarin, tetapi memakai huruf Latin (quoc ngu) sehingga lebih mudah dibaca pemula. Enam nada itu: ngang (datar), huyen (turun), sac (naik tajam), nang (turun berat), hoi (turun-naik), nga (naik putus). Tanda diakritik di atas huruf menunjukkan nadanya. Kabar baiknya: kosakata sehari-hari memakai pola yang berulang sehingga bisa dihafal bertahap.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Alat yang Dibutuhkan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Aplikasi kamus Vietnam-Indonesia (mis. kamus online atau aplikasi penerjemah)$txt$, $txt$Video pelafalan penutur asli untuk meniru nada$txt$, $txt$Catatan kecil berisi daftar sapaan harian$txt$, $txt$Partner latihan atau komunitas belajar bahasa$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah: Kuasai Sapaan Dasar$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Pelajari 10 sapaan inti: Xin chao (halo), Cam on (terima kasih), Xin loi (maaf), Tam biet (selamat tinggal), Vang/Khong (ya/tidak), Bao nhieu? (berapa harganya?), Toi khong hieu (saya tidak mengerti), Ban co noi tieng Anh khong? (apakah kamu bisa bahasa Inggris?)$txt$, $txt$Latih nada dengan mengucapkan tiap sapaan sambil meniru rekaman penutur asli, minimal 5 menit sehari$txt$, $txt$Hafalkan kata ganti orang: toi (saya), ban (kamu, sopan), anh (kakak laki-laki), chi (kakak perempuan), em (adik), ong/ba (bapak/ibu yang lebih tua)$txt$, $txt$Praktikkan perkenalan diri: Toi ten la ... (nama saya ...), Toi den tu Indonesia (saya dari Indonesia), Rat vui duoc gap ban (senang bertemu denganmu)$txt$, $txt$Gunakan sapaan sesuai usia lawan bicara — memanggil anh/chi/em dengan tepat adalah bentuk hormat terpenting$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Kesalahan Umum$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Mengabaikan nada sehingga Xin chao terdengar seperti kata lain — solusinya: dengarkan dan tiru, jangan hanya baca$txt$, $txt$Memanggil semua orang ban — padahal untuk yang lebih tua harus memakai ong, ba, co, chu sesuai hubungan$txt$, $txt$Terlalu malu untuk praktik — ingat, penutur asli justru senang membantu pemula yang berusaha$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Penyelesaian dan Tindak Lanjut$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Uji dirimu: bisakah kamu menyapa, memperkenalkan nama dan asal, bertanya harga, dan mengucapkan terima kasih serta maaf tanpa melihat catatan? Jika ya, fondasi sapaan dasarmu sudah kuat. Setelah sapaan dasar dikuasai, lanjutkan ke angka 1-100, nama makanan, dan arah jalan. Target 30 hari: mampu melakukan percakapan perkenalan 2 menit dengan penutur asli.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Tangan Sering Kesemutan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Kesemutan (parestesia) adalah sensasi seperti ditusuk-tusuk jarum kecil, biasanya di jari atau telapak tangan. Umumnya muncul setelah tangan tertindih atau berada dalam satu posisi terlalu lama, lalu hilang sendiri dalam beberapa menit. Namun jika kesemutan sering kambuh, berlangsung lama, atau disertai gejala lain, itu bisa menjadi tanda kondisi yang perlu perhatian medis.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Mengapa Tangan Kesemutan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Kesemutan terjadi ketika saraf tertekan atau aliran darah ke tangan terganggu sementara. Penyebab umum: posisi tidur menindih tangan, mengetik terlalu lama tanpa istirahat, carpal tunnel syndrome (saraf median terjepit di pergelangan), kekurangan vitamin B12, diabetes yang tidak terkontrol, atau gangguan sirkulasi. Pada kebanyakan kasus ringan, penyebabnya sederhana dan bisa diatasi dengan perubahan kebiasaan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Alat dan Persiapan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Air hangat untuk merendam tangan$txt$, $txt$Bantal atau penyangga pergelangan tangan (wrist rest)$txt$, $txt$Timer untuk pengingat istirahat saat bekerja$txt$, $txt$Catatan pola kesemutan (kapan muncul, berapa lama, tangan mana)$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah: Penanganan Mandiri di Rumah$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Goyang dan regangkan jari-jari tangan perlahan selama 1-2 menit untuk melancarkan aliran darah$txt$, $txt$Rendam tangan dalam air hangat 5-10 menit sambil pijat lembut telapak tangan$txt$, $txt$Perbaiki posisi kerja: pergelangan tangan lurus (tidak menekuk ke atas/bawah) saat mengetik atau memakai mouse$txt$, $txt$Istirahatkan tangan setiap 30-45 menit saat bekerja di depan komputer — regangkan jari dan putar pergelangan$txt$, $txt$Hindari tidur dengan tangan tertindih kepala atau badan; gunakan bantal yang menopang leher dengan baik$txt$, $txt$Jaga asupan vitamin B12 dari telur, susu, ikan, dan daging; batasi alkohol yang bisa merusak saraf$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Tanda Bahaya$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Segera ke dokter jika: kesemutan disertai kelemahan tangan (sulit menggenggam), nyeri menjalar ke leher/bahu, kesemutan hanya di satu sisi tubuh disertai wajah mencong atau bicara pelo (bisa tanda stroke — ke IGD segera)$txt$, $txt$Jangan memijat terlalu keras atau mengurut dengan tenaga besar — bisa memperparah saraf yang terjepit$txt$, $txt$Jangan mengabaikan kesemutan yang makin sering dan makin lama — catat polanya dan konsultasikan$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Penyelesaian dan Tindak Lanjut$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Evaluasi setelah 2 minggu: apakah frekuensi kesemutan berkurang dengan perbaikan posisi dan istirahat teratur? Jika membaik, lanjutkan kebiasaan baiknya. Jika tidak berubah atau memburuk, saatnya konsultasi ke dokter. Artikel ini bersifat info umum dan bukan pengganti nasihat medis. Jika kesemutan menetap, berulang, atau disertai gejala lain, konsultasikan ke dokter untuk pemeriksaan lebih lanjut — dokter mungkin menyarankan tes darah, pemeriksaan saraf, atau fisioterapi sesuai penyebabnya.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Indonesia: Negara Kepulauan di Atas Palung Dalam$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Indonesia tidak hanya punya pantai indah — di bawah permukaannya tersembunyi beberapa titik laut terdalam di dunia. Pertemuan lempeng tektonik Indo-Australia, Eurasia, dan Pasifik menciptakan palung-palung samudra yang kedalamannya mencapai ribuan meter, jauh di bawah jangkauan cahaya matahari.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Weber Deep: Titik Terdalam Indonesia$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Weber Deep di Laut Banda, Maluku, adalah titik terdalam di perairan Indonesia dengan kedalaman sekitar 7.440 meter. Palung ini terbentuk dari aktivitas tektonik kompleks di kawasan Wallacea. Saking dalamnya, tekanan di dasarnya lebih dari 700 kali tekanan udara di permukaan — setara ditindih ratusan gajah.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Palung Jawa: Parit Raksasa di Selatan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Palung Jawa (Java Trench) membentang di selatan Pulau Jawa dan Sumatra dengan kedalaman maksimum sekitar 7.290 meter. Palung inilah zona subduksi tempat Lempeng Indo-Australia menunjam ke bawah Lempeng Eurasia — sumber gempa besar dan tsunami, termasuk tsunami Aceh 2004 yang pusatnya berada di ujung barat palung ini.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Laut Banda dan Palung Tanimbar$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Laut Banda sendiri memiliki cekungan dalam hingga lebih dari 5.000 meter, sementara Palung Tanimbar di selatan Maluku mencapai sekitar 5.400 meter. Kawasan ini adalah bagian dari Cincin Api Pasifik dan menjadi laboratorium alam bagi ilmuwan yang mempelajari tektonik lempeng.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Kehidupan di Kegelapan Abadi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Di kedalaman lebih dari 1.000 meter tidak ada cahaya matahari sama sekali. Makhluk yang hidup di palung-palung Indonesia beradaptasi dengan cara luar biasa: tubuh transparan, organ penghasil cahaya sendiri (bioluminesensi), dan metabolisme super lambat. Banyak spesies di sana belum pernah dideskripsikan ilmuwan — setiap ekspedisi berpotensi menemukan spesies baru.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Baterai: Jantung Perangkat Modern$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Hampir semua perangkat modern — dari HP, laptop, hingga mobil listrik — bergantung pada baterai. Tanpa kemajuan teknologi baterai, tidak akan ada smartphone tipis, kendaraan listrik, atau penyimpanan energi surya skala besar. Baterai adalah salah satu teknologi paling menentukan abad ini.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Cara Kerja Baterai Lithium-Ion$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Baterai lithium-ion yang dipakai HP dan mobil listrik bekerja dengan memindahkan ion lithium antara dua elektroda (katoda dan anoda) melalui elektrolit. Saat dipakai, ion bergerak dari anoda ke katoda dan melepaskan elektron yang mengalir sebagai arus listrik. Saat di-charge, prosesnya dibalik. Siklus ini bisa diulang ratusan hingga ribuan kali sebelum kapasitasnya menurun.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Keterbatasan Baterai Saat Ini$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Baterai lithium-ion punya tiga kelemahan utama: kepadatan energi terbatas (mobil listrik butuh baterai ratusan kilogram), waktu pengisian yang masih lama dibanding isi bensin, dan risiko kebakaran jika rusak atau overheat (thermal runaway). Selain itu, bahan bakunya — lithium, kobalt, nikel — terbatas dan penambangannya berdampak lingkungan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Baterai Solid-State: Kandidat Pengganti$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Baterai solid-state mengganti elektrolit cair dengan elektrolit padat. Keuntungannya: jauh lebih aman (tidak mudah terbakar), kepadatan energi 2-3 kali lipat, dan pengisian lebih cepat. Banyak produsen mobil menargetkan produksi massal dalam dekade ini, meski biaya produksinya masih mahal.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Masa Depan: Natrium, Hidrogen, dan Daur Ulang$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Peneliti juga mengembangkan baterai natrium-ion (bahan baku melimpah dan murah), baterai aliran untuk penyimpanan energi skala jaringan listrik, dan teknologi daur ulang baterai bekas untuk menambang kembali lithium dan kobaltnya. Masa depan energi bersih sangat bergantung pada siapa yang memenangkan lomba teknologi baterai ini.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah mempelajari materi ini, siswa diharapkan mampu menjelaskan latar belakang pergerakan nasional, menyebutkan organisasi-organisasi pergerakan beserta tokohnya, dan memahami makna perjuangan mereka bagi kemerdekaan Indonesia.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Latar Belakang Pergerakan Nasional$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Pergerakan nasional lahir dari penderitaan rakyat akibat penjajahan Belanda: pajak yang memberatkan, kerja paksa, dan diskriminasi. Pendidikan yang dibawa Belanda justru melahirkan kaum terpelajar pribumi yang sadar bahwa bangsanya harus merdeka. Ditambah pengaruh kemenangan Jepang atas Rusia (1905) yang membuktikan bangsa Asia bisa mengalahkan bangsa Eropa.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Organisasi-Organisasi Pergerakan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Budi Utomo (1908) — didirikan Dr. Sutomo dan para mahasiswa STOVIA; dianggap sebagai awal kebangkitan nasional$txt$, $txt$Sarekat Islam (1911) — berawal dari Sarekat Dagang Islam pimpinan H. Samanhudi; menjadi organisasi massa terbesar$txt$, $txt$Indische Partij (1912) — Douwes Dekker, Cipto Mangunkusumo, Ki Hajar Dewantara; menuntut Indonesia merdeka$txt$, $txt$Perhimpunan Indonesia — organisasi pelajar Indonesia di Belanda; Mohammad Hatta aktif di sini$txt$, $txt$PNI (1927) — didirikan Soekarno; bertujuan Indonesia merdeka dengan asas marhaenisme$txt$, $txt$Taman Siswa (1922) — Ki Hajar Dewantara; pendidikan sebagai alat perjuangan$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Sumpah Pemuda 1928$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Puncak persatuan pergerakan adalah Kongres Pemuda II pada 27-28 Oktober 1928 di Jakarta. Para pemuda dari berbagai daerah mengikrarkan Sumpah Pemuda: bertanah air satu, berbangsa satu, berbahasa satu — Indonesia. Lagu Indonesia Raya ciptaan W.R. Supratman pertama kali diperdengarkan dalam kongres ini.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Latihan Soal$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Jelaskan tiga faktor pendorong lahirnya pergerakan nasional Indonesia!$txt$, $txt$Sebutkan tiga organisasi pergerakan beserta tokoh pendirinya!$txt$, $txt$Mengapa Sumpah Pemuda 1928 dianggap tonggak penting persatuan Indonesia?$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$1) Penderitaan rakyat akibat penjajahan, 2) lahirnya kaum terpelajar pribumi, 3) kemenangan Jepang atas Rusia 1905 yang membangkitkan kepercayaan diri bangsa Asia$txt$, $txt$Budi Utomo — Dr. Sutomo; Sarekat Islam — H. Samanhudi; PNI — Soekarno (jawaban lain yang benar juga diterima)$txt$, $txt$Karena untuk pertama kalinya pemuda dari berbagai suku dan daerah menyatakan diri sebagai satu bangsa Indonesia dengan satu bahasa persatuan — fondasi identitas nasional$txt$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah belajar materi ini, kamu diharapkan bisa menjelaskan apa itu peta, menyebutkan unsur-unsur peta, dan membaca peta sederhana seperti peta kelas atau peta lingkungan sekolah.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Apa Itu Peta?$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Peta adalah gambaran permukaan bumi pada bidang datar dengan skala tertentu. Dengan peta, kita bisa mengetahui letak suatu tempat, jarak antar tempat, dan arah tanpa harus pergi ke sana. Contoh peta yang sering kamu lihat: peta Indonesia di dinding kelas dan peta di aplikasi navigasi HP orang tuamu.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Unsur-Unsur Peta$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Judul peta — menjelaskan isi peta, misalnya Peta Provinsi Jawa Barat$txt$, $txt$Skala — perbandingan jarak di peta dengan jarak sebenarnya, misalnya 1:100.000$txt$, $txt$Mata angin — menunjukkan arah mata angin (utara, selatan, timur, barat)$txt$, $txt$Legenda — keterangan simbol-simbol pada peta, misalnya garis biru artinya sungai$txt$, $txt$Simbol — tanda khusus seperti segitiga untuk gunung dan titik untuk kota$txt$, $txt$Warna — hijau untuk dataran rendah, cokelat untuk pegunungan, biru untuk laut$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Cara Membaca Peta Sederhana$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Baca judul peta dulu agar tahu isi petanya$txt$, $txt$Perhatikan legenda untuk memahami arti simbol dan warna$txt$, $txt$Gunakan mata angin untuk menentukan arah suatu tempat — ada 8 arah: utara, timur laut, timur, tenggara, selatan, barat daya, barat, dan barat laut. Matahari terbit di timur dan terbenam di barat, ini cara termudah menentukan arah tanpa kompas$txt$, $txt$Gunakan skala untuk memperkirakan jarak sebenarnya$txt$, $txt$Contoh: pada peta sekolah, cari simbol kantin, lalu tentukan arahnya dari kelasmu$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Latihan Soal$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Apa yang dimaksud dengan peta?$txt$, $txt$Sebutkan 4 unsur peta beserta fungsinya!$txt$, $txt$Matahari terbit di arah mana? Bagaimana cara menentukannya?$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Peta adalah gambaran permukaan bumi pada bidang datar dengan skala tertentu$txt$, $txt$Judul (menjelaskan isi peta), skala (perbandingan jarak), mata angin (menunjukkan arah), legenda (keterangan simbol) — jawaban unsur lain yang benar juga diterima$txt$, $txt$Timur; dengan melihat tempat matahari terbit di pagi hari$txt$])));
